import{_ as t,a,b as i}from"./chunks/details-yaml.FET-twd8.js";import{_ as o,o as s,c as n,a3 as r}from"./chunks/framework.BlfGB29P.js";const g=JSON.parse('{"title":"Home Assistant Automation Exporter","description":"English documentation for the Windows tool for exporting individual Home Assistant automations from automations.yaml.","frontmatter":{"title":"Home Assistant Automation Exporter","description":"English documentation for the Windows tool for exporting individual Home Assistant automations from automations.yaml."},"headers":[],"relativePath":"en/collection/ha-automation-exporter/index.md","filePath":"en/collection/ha-automation-exporter/index.md","lastUpdated":1793127012000}'),l={name:"en/collection/ha-automation-exporter/index.md"};function d(h,e,c,p,m,u){return s(),n("div",null,[...e[0]||(e[0]=[r('<p><a id="current-focus"></a></p><h1 id="home-assistant-automation-exporter" tabindex="-1">Home Assistant Automation Exporter <a class="header-anchor" href="#home-assistant-automation-exporter" aria-label="Permalink to &quot;Home Assistant Automation Exporter {#home-assistant-automation-exporter}&quot;">​</a></h1><p>The <strong>Home Assistant Automation Exporter</strong> is a portable Windows tool that can be used to read a Home Assistant file <code>automations.yaml</code> and export it to individual YAML files.</p><p>This is helpful if automations are to be saved separately, passed on, documented or later imported back into Home Assistant individually.</p><p><img src="'+t+'" alt="Home Assistant Automation Exporter"></p><h2 id="projekt" tabindex="-1">Project <a class="header-anchor" href="#projekt" aria-label="Permalink to &quot;Project {#projekt}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Entry</th><th>Link</th></tr></thead><tbody><tr><td>GitHub repository</td><td><a href="https://github.com/rockbaer2007/ha-automation-exporter" target="_blank" rel="noreferrer">rockbaer2007/ha-automation-exporter</a></td></tr><tr><td>Current Release</td><td><a href="https://github.com/rockbaer2007/ha-automation-exporter/releases/tag/v0.3.4" target="_blank" rel="noreferrer">Download v0.3.4</a></td></tr><tr><td>Platform</td><td>Windows</td></tr><tr><td>base</td><td>C# / .NET 9</td></tr></tbody></table><h2 id="funktionen" tabindex="-1">Features <a class="header-anchor" href="#funktionen" aria-label="Permalink to &quot;Features {#funktionen}&quot;">​</a></h2><ul><li>Opens a Windows interface without a command line.</li><li>Shows the program version in the window title.</li><li>Reads a Home Assistant <code>automations.yaml</code>.</li><li>Searches automations by alias, ID, filename or YAML content.</li><li>Shows all automations in a table with selection fields.</li><li>Opens detailed views with recognized entities and full YAML code.</li><li>Exports selected automations as individual <code>.yaml</code> files.</li><li>Opens the selected export folder directly in Windows Explorer.</li><li>Stores settings portably next to the EXE in <code>HaAutomationExporter.settings.json</code>.</li></ul><h2 id="voraussetzungen" tabindex="-1">Requirements <a class="header-anchor" href="#voraussetzungen" aria-label="Permalink to &quot;Requirements {#voraussetzungen}&quot;">​</a></h2><p>For use as a finished release:</p><ul><li>Windows</li><li>Download the current release file from GitHub</li></ul><p>For development or starting from source code:</p><ul><li>Windows</li><li>.NET 9 SDK</li><li>Repository cloned locally</li></ul><div class="language-powershell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">dotnet run </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">--</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">project .\\HaAutomationExporter.csproj</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h2 id="bedienung" tabindex="-1">Service <a class="header-anchor" href="#bedienung" aria-label="Permalink to &quot;Service {#bedienung}&quot;">​</a></h2><ol><li>Start the program.</li><li>Select the Home Assistant file <code>automations.yaml</code>.</li><li>Optionally change the export folder in the settings.</li><li>Select automations in the table.</li><li>Check individual automations via <code>Details</code>.</li><li>Export selected automations.</li><li>Import the generated YAML files into Home Assistant if necessary.</li></ol><h2 id="detailansicht" tabindex="-1">Detailed view <a class="header-anchor" href="#detailansicht" aria-label="Permalink to &quot;Detailed view {#detailansicht}&quot;">​</a></h2><p>In the detailed view, an automation can be checked before exporting. This is particularly useful when many automations have similar names or when you want to control templates and entities.</p><p><img src="'+a+'" alt="Automation Details: Entities"></p><p>The <strong>Entities</strong> tab shows recognized Home Assistant entities with source, line number and context. Template hits are recognized heuristically.</p><p><img src="'+i+`" alt="Automation Details: YAML"></p><p>The <strong>YAML</strong> tab shows the complete automation code and contains a copy function.</p><h2 id="export-fur-home-assistant" tabindex="-1">Export for Home Assistant <a class="header-anchor" href="#export-fur-home-assistant" aria-label="Permalink to &quot;Export for Home Assistant {#export-fur-home-assistant}&quot;">​</a></h2><p>The exported files are prepared to make them easier to use individually in Home Assistant.</p><p>The exporter removes the leading top line <code>id:</code> and normalizes different YAML notations:</p><table tabindex="0"><thead><tr><th>exit</th><th>Export</th></tr></thead><tbody><tr><td><code>triggers</code></td><td><code>trigger</code></td></tr><tr><td><code>conditions</code></td><td><code>condition</code></td></tr><tr><td><code>actions</code></td><td><code>action</code></td></tr><tr><td><code>- trigger: ...</code></td><td><code>- platform: ...</code></td></tr><tr><td>Service actions</td><td><code>- service: domain.service</code></td></tr></tbody></table><p>This allows automations from different Home Assistant versions, GitHub examples or forum posts to be exported more consistently.</p><h2 id="sprachen" tabindex="-1">Languages <a class="header-anchor" href="#sprachen" aria-label="Permalink to &quot;Languages {#sprachen}&quot;">​</a></h2><p>The interface supports:</p><ul><li>system</li><li>German</li><li>English</li><li>French</li><li>Spanish</li><li>Polish</li><li>Russian</li></ul><p>The <code>System</code> option detects the Windows language for <code>de</code>, <code>en</code>, <code>fr</code>, <code>es</code>, <code>pl</code>, and <code>ru</code>. System languages that are not supported fall back to English.</p><h2 id="kommandozeile" tabindex="-1">Command line <a class="header-anchor" href="#kommandozeile" aria-label="Permalink to &quot;Command line {#kommandozeile}&quot;">​</a></h2><p>The project is built as a Windows application so that it starts without a console window. Arguments can still be processed internally.</p><div class="language-powershell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">HaAutomationExporter.exe</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> C:\\path\\automations.yaml C:\\path\\export</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">HaAutomationExporter.exe</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> C:\\path\\automations.yaml C:\\path\\export pool</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>The graphical interface is intended for normal use.</p><h2 id="hinweise" tabindex="-1">Notes <a class="header-anchor" href="#hinweise" aria-label="Permalink to &quot;Notes {#hinweise}&quot;">​</a></h2><ul><li>Before importing into Home Assistant, each exported automation should be briefly checked.</li><li>Automations with complex templates may require manual control.</li><li>The original file <code>automations.yaml</code> is only read and not changed.</li><li>The export folder should be outside of the productive Home Assistant configuration until the files are checked.</li></ul>`,38)])])}const x=o(l,[["render",d]]);export{g as __pageData,x as default};
